contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(bytes32 h) public payable {
        require(address(this).balance >= 1 ether);

        // The fresh tester has never locked in a guess, so the require(guesses[msg.sender].block == 0)
        // precondition of lockInGuess passes. A correct P must accept the call with exactly 1 ether.
        bool lockReverted;
        try c.lockInGuess{value: 1 ether}(h) {
            lockReverted = false;
        } catch {
            lockReverted = true;
        }

        // Since lockInGuess succeeded, the guess must be stored and settle() must revert,
        // because settle() requires block.number > guesses[msg.sender].block and the
        // stored block is the current block.number + 1.
        bool settleReverted;
        try c.settle() {
            settleReverted = false;
        } catch {
            settleReverted = true;
        }

        assert(!lockReverted && settleReverted);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(bytes32 h1, bytes32 h2) public payable {
        require(address(this).balance >= 2 ether);

        // First lock-in must succeed on a fresh contract from this test account.
        c.lockInGuess{value: 1 ether}(h1);

        // A second lock-in from the same account must revert because an active guess exists.
        bool secondLockReverted;
        try c.lockInGuess{value: 1 ether}(h2) {
            secondLockReverted = false;
        } catch {
            secondLockReverted = true;
        }

        assert(secondLockReverted);
    }

    receive() external payable {}
}

