contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function run(bytes32 guess, uint lockValue, uint settleValue) public payable {
        require(lockValue == 1 ether, "lock value must be exactly 1 ether");
        require(address(this).balance >= lockValue, "insufficient balance for lock");

        c.lockInGuess{value: lockValue}(guess);

        bool settledReverted;
        try c.settle() {
            settledReverted = false;
        } catch {
            settledReverted = true;
        }

        assert(!settledReverted);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function run(bytes32 guess) public payable {
        // Try to settle without ever locking in a guess. Since guesses[msg.sender].block == 0,
        // the require(guesses[msg.sender].block != 0) must fail and settle() must revert.
        bool reverted;
        try c.settle() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: settling without a pending guess always reverts.
        assert(reverted);
    }

    receive() external payable {}
}
